#include <cstdio>
#include <vector>
#include <algorithm>

struct Interval { long long l, r; };

int main() {
    int n;
    scanf("%d", &n);
    std::vector<Interval> segs(n);
    for (int i = 0; i < n; ++i) scanf("%lld %lld", &segs[i].l, &segs[i].r);

    std::sort(segs.begin(), segs.end(), [](const Interval& a, const Interval& b) {
        return a.l < b.l;
    });

    std::vector<Interval> merged;
    for (int i = 0; i < n; ++i) {
        if (!merged.empty() && segs[i].l <= merged.back().r + 1) {
            if (segs[i].r > merged.back().r) merged.back().r = segs[i].r;
        } else {
            merged.push_back(segs[i]);
        }
    }

    printf("%d\n", (int)merged.size());
    for (const auto& s : merged) printf("%lld %lld\n", s.l, s.r);
    return 0;
}
